using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
public sealed class AppUpdates {
 public const string Current="0.11.0";
 const string Repo="https://api.github.com/repos/yuri434/yuri-music/releases/latest";
 readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=2097152};
 bool busy;
 static string Str(Dictionary<string,object> d,string key){return d.ContainsKey(key)?Convert.ToString(d[key]):"";}
 public static Version ParseVersion(string value){if(!Regex.IsMatch(value??"",@"^v?\d+\.\d+\.\d+$"))throw new IOException("Versão da atualização inválida.");return new Version(value.TrimStart('v'));}
 static HttpClient Client(){System.Net.ServicePointManager.SecurityProtocol|=System.Net.SecurityProtocolType.Tls12;var h=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false});h.Timeout=TimeSpan.FromMinutes(8);h.DefaultRequestHeaders.UserAgent.ParseAdd("YuriMusic/"+Current);h.DefaultRequestHeaders.Accept.ParseAdd("application/vnd.github+json");return h;}
 public static bool Allowed(Uri u){return u.Scheme=="https"&&(u.Host=="github.com"||u.Host=="api.github.com"||u.Host=="release-assets.githubusercontent.com"||u.Host=="objects.githubusercontent.com");}
 static async Task<HttpResponseMessage> Open(HttpClient client,string url){for(int i=0;i<6;i++){var uri=new Uri(url);if(!Allowed(uri))throw new IOException("Origem da atualização inválida.");var response=await client.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead);if((int)response.StatusCode>=300&&(int)response.StatusCode<400){var location=response.Headers.Location;response.Dispose();if(location==null)throw new IOException("Redirecionamento inválido.");url=new Uri(uri,location).AbsoluteUri;continue;}if(!response.IsSuccessStatusCode){response.Dispose();throw new IOException("Não foi possível consultar ou baixar a atualização. Tente novamente mais tarde.");}return response;}throw new IOException("Redirecionamentos demais.");}
 static async Task<byte[]> Read(HttpClient client,string url,int limit){using(var response=await Open(client,url)){if(response.Content.Headers.ContentLength>limit)throw new IOException("Arquivo de atualização muito grande.");using(var input=await response.Content.ReadAsStreamAsync())using(var output=new MemoryStream()){byte[] buffer=new byte[65536];int n;while((n=await input.ReadAsync(buffer,0,buffer.Length))>0){if(output.Length+n>limit)throw new IOException("Arquivo de atualização muito grande.");output.Write(buffer,0,n);}return output.ToArray();}}}
 public async Task<Dictionary<string,object>> Latest(){using(var client=Client()){var release=json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(await Read(client,Repo,2097152)));ParseVersion(Str(release,"tag_name"));if(Convert.ToBoolean(release["draft"])||Convert.ToBoolean(release["prerelease"]))throw new IOException("Esta versão ainda não está disponível.");return release;}}
 static Dictionary<string,object> Asset(Dictionary<string,object> release,string name){var assets=(System.Collections.IEnumerable)release["assets"];foreach(Dictionary<string,object> asset in assets)if(Str(asset,"name")==name){var u=new Uri(Str(asset,"browser_download_url"));if(u.Host!="github.com"||!u.AbsolutePath.StartsWith("/yuri434/yuri-music/releases/download/",StringComparison.Ordinal)||u.Scheme!="https")throw new IOException("Link de atualização inválido.");return asset;}throw new IOException("Os arquivos desta atualização ainda não estão prontos. Tente novamente depois.");}
 public async Task<object> Check(){var release=await Latest();string latest=Str(release,"tag_name").TrimStart('v');bool available=ParseVersion(latest)>ParseVersion(Current);bool ready=false;if(available){try{Asset(release,"YuriMusic-Windows-"+latest+".zip");Asset(release,"SHA256SUMS-"+latest+".txt");ready=true;}catch{}}return new{current=Current,latest=latest,available=available,ready=ready,platform="windows",message=available?(ready?"Versão "+latest+" disponível.":"A nova versão está sendo preparada. Tente mais tarde."):"Você está na versão mais recente."};}
 public static string Hash(string file){using(var sha=SHA256.Create())using(var input=File.OpenRead(file))return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}
 public static string ExpectedHash(string text,string name){foreach(string line in text.Split('\n')){var match=Regex.Match(line.Trim(),@"^([a-fA-F0-9]{64})\s+\*?(.+)$");if(match.Success&&match.Groups[2].Value==name)return match.Groups[1].Value.ToLowerInvariant();}throw new IOException("Não foi possível verificar a integridade da atualização.");}
 public async Task<string> Stage(string expected){if(busy)throw new IOException("Uma atualização já está em andamento.");busy=true;try{var release=await Latest();string version=Str(release,"tag_name").TrimStart('v');if(version!=expected||ParseVersion(version)<=ParseVersion(Current))throw new IOException("Confira novamente as atualizações antes de instalar.");string name="YuriMusic-Windows-"+version+".zip";var asset=Asset(release,name);var sums=Asset(release,"SHA256SUMS-"+version+".txt");string stage=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"YuriMusic","Updates",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);using(var client=Client()){string hash=ExpectedHash(Encoding.UTF8.GetString(await Read(client,Str(sums,"browser_download_url"),65536)),name);string archive=Path.Combine(stage,"update.zip");using(var response=await Open(client,Str(asset,"browser_download_url"))){const long max=300L*1024*1024;if(response.Content.Headers.ContentLength>max)throw new IOException("Atualização muito grande.");using(var input=await response.Content.ReadAsStreamAsync())using(var output=File.Create(archive)){byte[] block=new byte[65536];int n;long total=0;while((n=await input.ReadAsync(block,0,block.Length))>0){total+=n;if(total>max)throw new IOException("Atualização muito grande.");await output.WriteAsync(block,0,n);}}}if(Hash(archive)!=hash)throw new IOException("O download não passou na verificação. Tente novamente.");Extract(archive,Path.Combine(stage,"payload"),"YuriMusic-Windows-"+version);}return stage;}finally{busy=false;}}
 public static void Extract(string archive,string destination,string prefix){string full=Path.GetFullPath(destination)+Path.DirectorySeparatorChar;Directory.CreateDirectory(destination);var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long total=0;using(var zip=ZipFile.OpenRead(archive)){if(zip.Entries.Count>30000)throw new IOException("Pacote inválido.");foreach(var entry in zip.Entries){string name=entry.FullName.Replace('\\','/');if(!name.StartsWith(prefix+"/",StringComparison.Ordinal))throw new IOException("Estrutura de atualização inválida.");string relative=name.Substring(prefix.Length+1);if(relative.Length==0)continue;if(relative.Contains(":")||relative.Split('/').Any(part=>part==".."||part=="."))throw new IOException("Caminho inválido no pacote.");string target=Path.GetFullPath(Path.Combine(destination,relative.Replace('/',Path.DirectorySeparatorChar)));if(!target.StartsWith(full,StringComparison.OrdinalIgnoreCase))throw new IOException("Caminho inválido no pacote.");if(name.EndsWith("/")){Directory.CreateDirectory(target);continue;}if(!seen.Add(target)||(entry.ExternalAttributes>>16&0xF000)==0xA000)throw new IOException("Pacote inválido.");total+=entry.Length;if(total>1024L*1024*1024)throw new IOException("Pacote muito grande.");Directory.CreateDirectory(Path.GetDirectoryName(target));entry.ExtractToFile(target,false);}}if(!File.Exists(Path.Combine(destination,"YuriMusic-YouTube.exe"))||!File.Exists(Path.Combine(destination,"web","index.html"))||!File.Exists(Path.Combine(destination,"YuriMusicUpdater.exe")))throw new IOException("A atualização está incompleta.");}
}

